'use strict';

// MODULES //

var tape = require( 'tape' );
var Uint32Array = require( '@stdlib/array/uint32' );
var isEqualUint32Array = require( '@stdlib/assert/is-equal-uint32array' );
var rightShift = require( './../lib/strided.js' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof rightShift, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function performs bitwise shift to the right on a 64-bit unsigned integer', function test( t ) {
	var expected;
	var out;
	var a;
	var v;

	// Trivial stride and offset:
	a = new Uint32Array( [ 2, 4 ] );
	out = new Uint32Array( 2 );
	v = rightShift( a, 1, 0, 1, out, 1, 0 );
	expected = new Uint32Array( [ 1, 2 ] );
	t.strictEqual( v, out, 'returns expected value' );
	t.strictEqual( isEqualUint32Array( out, expected ), true, 'returns expected value' );

	// Positive stride:
	a = new Uint32Array( [ 2, 0, 0, 4, 0, 0 ] );
	out = new Uint32Array( 2 );
	v = rightShift( a, 3, 0, 1, out, 1, 0 );
	expected = new Uint32Array( [ 1, 2 ] );
	t.strictEqual( v, out, 'returns expected value' );
	t.strictEqual( isEqualUint32Array( out, expected ), true, 'returns expected value' );

	// Positive stride and non-zero offset:
	a = new Uint32Array( [ 0, 0, 2, 0, 0, 4 ] );
	out = new Uint32Array( 2 );
	v = rightShift( a, 3, 2, 1, out, 1, 0 );
	expected = new Uint32Array( [ 1, 2 ] );
	t.strictEqual( v, out, 'returns expected value' );
	t.strictEqual( isEqualUint32Array( out, expected ), true, 'returns expected value' );

	// Negative stride and non-zero offset:
	a = new Uint32Array( [ 0, 0, 4, 0, 0, 2 ] );
	out = new Uint32Array( 2 );
	v = rightShift( a, -3, 5, 1, out, 1, 0 );
	expected = new Uint32Array( [ 1, 2 ] );
	t.strictEqual( v, out, 'returns expected value' );
	t.strictEqual( isEqualUint32Array( out, expected ), true, 'returns expected value' );

	t.end();
});
